unsigned int pcibios_handle_status_errors ( unsigned long addr , unsigned int status , struct pci_channel * hose ) { unsigned int cmd = 0 ; if ( status & PCI_STATUS_REC_MASTER_ABORT ) { printk ( KERN_DEBUG "PCI: master abort, pc=0x%08lx\n" , addr ) ; cmd |= PCI_STATUS_REC_MASTER_ABORT ; } if ( status & PCI_STATUS_REC_TARGET_ABORT ) { printk ( KERN_DEBUG "PCI: target abort: " ) ; pcibios_report_status ( PCI_STATUS_REC_TARGET_ABORT | PCI_STATUS_SIG_TARGET_ABORT | PCI_STATUS_REC_MASTER_ABORT , 1 ) ; pr_cont ( "\n" ) ; cmd |= PCI_STATUS_REC_TARGET_ABORT ; } if ( status & ( PCI_STATUS_PARITY | PCI_STATUS_DETECTED_PARITY ) ) { printk ( KERN_DEBUG "PCI: parity error detected: " ) ; pcibios_report_status ( PCI_STATUS_PARITY | PCI_STATUS_DETECTED_PARITY , 1 ) ; pr_cont ( "\n" ) ; cmd |= PCI_STATUS_PARITY | PCI_STATUS_DETECTED_PARITY ; if ( hose -> err_irq ) { hose -> err_timer . expires = jiffies + HZ ; add_timer ( & hose -> err_timer ) ; } } return cmd ; } 